    N, Q = map(int, input[ptr:ptr+2])
    ptr += 2

    adj = [[] for _ in range(N+1)]
    for _ in range(N-1):
        u, v = map(int, input[ptr:ptr+2])
        ptr += 2
        adj[u].append(v)
        adj[v].append(u)

    A = [0] + list(map(int, input[ptr:ptr+N]))
    ptr += N

    queries = []
    for _ in range(Q):
        parts = input[ptr]
        if parts == '1':
            v, x = map(int, input[ptr+1:ptr+3])
            queries.append((1, v, x))
            ptr += 3
        else:
            v = int(input[ptr+1])
            queries.append((2, v))
            ptr += 2

    parent = [0]*(N+1)
    depth = [0]*(N+1)
    size = [0]*(N+1)
    vis = [0]*(N+1)

    # BFS to set up parent and depth
    q = deque([1])
    parent[1] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    # Compute subtree sizes
    stack = [(1, False)]
    while stack:
        u, processed = stack.pop()
        if not processed:
            stack.append((u, True))
            for v in adj[u]:
                if v != parent[u]:
                    stack.append((v, False))
        else:
            size[u] = 1
            for v in adj[u]:
                if v != parent[u]:
                    size[u] += size[v]

