            u, processed = stack.pop()
            if not processed:
                stack.append((u, True))
                for child in adj[u]:
                    if child != parent[u]:
                        stack.append((child, False))
            else:
                res += vis[u]
                for child in adj[u]:
                    if child != parent[u]:
                        res += vis[child] * size[child]
        return res

