            A[v] = x
        else:
            v = query[1]
            # Reset vis
            vis = [0]*(N+1)
            # Perform DFS
            stack = [(1, -1)]
            while stack:
                u, p = stack.pop()
                vis[u] += 1
                for _ in range(A[u]):
                    for child in adj[u]:
                        if child != p:
                            stack.append((child, u))
            # Compute sum for subtree of v
            res = 0
            stack = [(v, False)]
            while stack:
                u, processed = stack.pop()
                if not processed:
                    stack.append((u, True))
                    for child in adj[u]:
                        if child != parent[u]:
                            stack.append((child, False))
                else:
                    res += vis[u]
                    for child in adj[u]:
                        if child != parent[u]:
                            res += vis[child] * size[child]
            output.append(str(res % MOD))

    print('\n'.join(output))

